--- from: Assets/BundleResources/Prefabs/ResidentEvent/ResdientAdventureDialog.prefab > name: ResidentAdventureDialog
---@class ResidentAdventureDialog
---@field Env                           	ResidentAdventureDialog                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field CommonGoodsListLight          	UnityEngine.RectTransform               	@ 0    
---@field BtnGoTo                       	UnityEngine.RectTransform               	@ 1    
---@field FontStyleButton               	UnityEngine.RectTransform               	@ 2    
local ResidentAdventureDialog = Class("ResidentAdventureDialog")

function ResidentAdventureDialog:__init()
    self.vo = nil
    self.link = nil
end

function ResidentAdventureDialog:__delete()
    self.vo = nil
    self.link = nil
    self.controller = nil
end

function ResidentAdventureDialog:Awake()
    SetButtonAction(self.BtnGoTo,Bind(self,self.OnBtnGoToClick))
    SetButtonAction(self.FontStyleButton,Bind(self,self.OnFontStyleButtonClick))

    self:RefreshRedPoint()
end

function ResidentAdventureDialog:RefreshRedPoint()
    local num = GameUtils.GetRedPointNum(Constants.RedPointConst.ResidentAdventure)
    CfUtils.SetActive(self.RedPoint.gameObject,num > 0)
end

function ResidentAdventureDialog:Refresh(data)
    if not data then return end
    self.data = data
    GameUtils.Request(Interfaces.OverseaWelfare,nil,function(request, response)
        if checkNumber(response.errCode) == 0 then
            local link = checkString(response.data.link)
            self.link = link
        end
    end)
    
    
    local state = self:GetBtnState()
    self:SetBtnState(state)

    self.vo = CfUtils.GetCfVo(AutoIds.IdSetting6463,"WebsiteJumpVo",1)
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, self.vo.rewards,nil,state == Constants.GetStatus.Has)

end

function ResidentAdventureDialog:GetBtnState()
    local playerDojo = GameUtils.GetPlayerDojo()
    local isGet = playerDojo:IsGetWelfareJumpRewards()
    if isGet then
        return Constants.GetStatus.Has
    else
        local isCanGet = CfUtils.GetLocalData("ResidentAdventureJumpClick1",0)
        return checkNumber(isCanGet) == 1 and Constants.GetStatus.Can or Constants.GetStatus.Not
    end
end

function ResidentAdventureDialog:OnBtnGoToClick()
    if isNotNull(self.vo) and not string.isEmpty(self.link) then
        CfUtils.WriteLocalData("ResidentAdventureJumpClick1",1)
        CfUtils.OpenURL(self.link)
        local state = self:GetBtnState()
        self:SetBtnState(state)
    end
end

function ResidentAdventureDialog:OnFontStyleButtonClick()
    local state = self:GetBtnState()
    if state == Constants.GetStatus.Can then
        GameUtils.Request(Interfaces.WelfareJumpReward,nil,function(request,response)
            if checkNumber(response.errCode) == 0 then
                local responseData = response.data
                local playerDojo = GameUtils.GetPlayerDojo()
                playerDojo:UpdateWelfareJumpState(1)
                GameUtils.SetRedPointNum(Constants.RedPointConst.ResidentAdventure, 0)
                self:RefreshRedPoint()
                if table.count(responseData.rewards) > 0 then
                    GoodsUtils.DrawRewards(responseData.rewards)
                    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                    local state = self:GetBtnState()
                    self:SetBtnState(state)
                end
            end
        end)
    end
end

function ResidentAdventureDialog:SetBtnState(status)
    CfUtils.SetActive(self.BtnGoTo.gameObject,status == Constants.GetStatus.Not)
    CfUtils.SetActive(self.FontStyleButton.gameObject,status ~= Constants.GetStatus.Not)

    if status == Constants.GetStatus.Can then
        CfUtils.SetButtonStyle(self.FontStyleButton, 'B1', localize('领取'))
    elseif status == Constants.GetStatus.Has then
        CfUtils.SetButtonStyle(self.FontStyleButton, 'B17', localize('已领取'))
    end
end

function ResidentAdventureDialog:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ResidentAdventureDialog